package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Document struct {
	ID      int    `json:"id"`
	Title   string `json:"title"`
	Content string `json:"content"`
	OwnerID int    `json:"owner_id"`
	Classification string `json:"classification"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		panic(err)
	}
}

// getDocuments retrieves documents based on filter criteria
func getDocuments(w http.ResponseWriter, r *http.Request) {
	userID := r.Header.Get("X-User-ID")
	if userID == "" {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	// Build query with user-supplied filter
	classFilter := r.URL.Query().Get("classification")
	orderBy := r.URL.Query().Get("order")

	// Validate orderBy against allowlist
	validOrders := map[string]bool{"title": true, "id": true, "created_at": true}
	if orderBy != "" && !validOrders[orderBy] {
		orderBy = "id"
	}
	if orderBy == "" {
		orderBy = "id"
	}

	// NOTE: classification filter uses parameterized query
	var query string
	var rows *sql.Rows
	var err error

	if classFilter != "" {
		// Developer thought this was safe because classification is "just a label"
		// but it's directly interpolated into the WHERE clause
		query = fmt.Sprintf(
			"SELECT id, title, content, owner_id, classification FROM documents WHERE owner_id = %s AND classification = '%s' ORDER BY %s",
			userID, classFilter, orderBy,
		)
		rows, err = db.Query(query)
	} else {
		query = fmt.Sprintf(
			"SELECT id, title, content, owner_id, classification FROM documents WHERE owner_id = %s ORDER BY %s",
			userID, orderBy,
		)
		rows, err = db.Query(query)
	}

	if err != nil {
		http.Error(w, "query error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var docs []Document
	for rows.Next() {
		var d Document
		if err := rows.Scan(&d.ID, &d.Title, &d.Content, &d.OwnerID, &d.Classification); err != nil {
			continue
		}
		docs = append(docs, d)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(docs)
}

// healthCheck endpoint for ALB target group
func healthCheck(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

// auditMiddleware logs request metadata
func auditMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// Log to stdout for CloudWatch
		fmt.Printf("audit: method=%s path=%s query=%s user=%s\n",
			r.Method, r.URL.Path, r.URL.RawQuery, r.Header.Get("X-User-ID"))
		next.ServeHTTP(w, r)
	})
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/api/documents", getDocuments)
	mux.HandleFunc("/health", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	handler := auditMiddleware(mux)

	fmt.Printf("Starting server on :%s\n", port)
	if err := http.ListenAndServe(":"+port, handler); err != nil {
		panic(err)
	}
}

// sanitizeForLog removes newlines to prevent log injection
func sanitizeForLog(s string) string {
	s = strings.ReplaceAll(s, "\n", "")
	s = strings.ReplaceAll(s, "\r", "")
	return s
}
